final class BinarySearcher implements SearchAlgorithm {
    @Override
    public SearchResult search(int[] sortedArray, int target) {
        validateInput(sortedArray);

        int low = 0;
        int high = sortedArray.length - 1;

        while (low <= high) {
            int mid = low + (high - low) / 2;

            if (sortedArray[mid] == target) {
                return SearchResult.foundAt(mid);
            }

            if (sortedArray[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return SearchResult.notFound();
    }

    private static void validateInput(int[] sortedArray) {
        if (sortedArray == null) {
            throw new IllegalArgumentException("sortedArray must not be null");
        }
    }
}

final class BinarySearch {
    private static final SearchAlgorithm SEARCH_ALGORITHM = new BinarySearcher();

    private BinarySearch() {
    }

    static int binarySearch(int[] sortedArray, int target) {
        return SEARCH_ALGORITHM.search(sortedArray, target).index();
    }

    public static void main(String[] args) {
        BinarySearchDemo.run();
    }
}

final class BinarySearchDemo {
    private static final SearchAlgorithm SEARCH_ALGORITHM = new BinarySearcher();
    private static final SearchResultFormatter RESULT_FORMATTER = new DefaultSearchResultFormatter();

    private BinarySearchDemo() {
    }

    static void run() {
        run(SEARCH_ALGORITHM, RESULT_FORMATTER);
    }

    static void run(SearchAlgorithm searchAlgorithm, SearchResultFormatter resultFormatter) {
        validateDependencies(searchAlgorithm, resultFormatter);

        int[] sortedArray = { 2, 3, 4, 10, 40 };
        int target = 10;
        SearchResult result = searchAlgorithm.search(sortedArray, target);

        System.out.println(resultFormatter.format(result));
    }

    private static void validateDependencies(
            SearchAlgorithm searchAlgorithm,
            SearchResultFormatter resultFormatter) {
        if (searchAlgorithm == null) {
            throw new IllegalArgumentException("searchAlgorithm must not be null");
        }

        if (resultFormatter == null) {
            throw new IllegalArgumentException("resultFormatter must not be null");
        }
    }
}

final class BinarySearchDemo {
    private BinarySearchDemo() {
    }

    static void run() {
        run(SearchContainer.defaultContainer());
    }

    static void run(SearchAlgorithm searchAlgorithm, SearchResultFormatter resultFormatter) {
        run(SearchContainer.builder()
                .withSearchAlgorithm(searchAlgorithm)
                .withResultFormatter(resultFormatter)
                .build());
    }

    static void run(SearchContainer container) {
        validateContainer(container);

        int[] sortedArray = { 2, 3, 4, 10, 40 };
        int target = 10;
        SearchResult result = container.searchAlgorithm().search(sortedArray, target);

        System.out.println(container.resultFormatter().format(result));
    }

    private static void validateContainer(SearchContainer container) {
        if (container == null) {
            throw new IllegalArgumentException("container must not be null");
        }
    }
}

final class SearchContainer {
    private final SearchAlgorithm searchAlgorithm;
    private final SearchResultFormatter resultFormatter;

    private SearchContainer(Builder builder) {
        searchAlgorithm = requireConfigured(builder.searchAlgorithm, "searchAlgorithm");
        resultFormatter = requireConfigured(builder.resultFormatter, "resultFormatter");
    }

    static SearchContainer defaultContainer() {
        return builder()
                .withSearchAlgorithm(new BinarySearcher())
                .withResultFormatter(new DefaultSearchResultFormatter())
                .build();
    }

    static Builder builder() {
        return new Builder();
    }

    SearchAlgorithm searchAlgorithm() {
        return searchAlgorithm;
    }

    SearchResultFormatter resultFormatter() {
        return resultFormatter;
    }

    private static <T> T requireConfigured(T dependency, String name) {
        if (dependency == null) {
            throw new IllegalArgumentException(name + " must not be null");
        }

        return dependency;
    }

    static final class Builder {
        private SearchAlgorithm searchAlgorithm;
        private SearchResultFormatter resultFormatter;

        private Builder() {
        }

        Builder withSearchAlgorithm(SearchAlgorithm searchAlgorithm) {
            this.searchAlgorithm = searchAlgorithm;
            return this;
        }

        Builder withResultFormatter(SearchResultFormatter resultFormatter) {
            this.resultFormatter = resultFormatter;
            return this;
        }

        SearchContainer build() {
            return new SearchContainer(this);
        }
    }
}
